import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Tangazo la Ustaarabu wa Usawa wa Nanga","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0001-锚点共生文明宣言.md","filePath":"sw/0001-锚点共生文明宣言.md"}'),o={name:"sw/0001-锚点共生文明宣言.md"};function e(s,a,w,l,h,m){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="tangazo-la-ustaarabu-wa-usawa-wa-nanga" tabindex="-1">Tangazo la Ustaarabu wa Usawa wa Nanga <a class="header-anchor" href="#tangazo-la-ustaarabu-wa-usawa-wa-nanga" aria-label="Permalink to &quot;Tangazo la Ustaarabu wa Usawa wa Nanga&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>01</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Tangazo, Usawa, Kupinga Uwindaji, Kabila Kumi na Elfu, Haki ya Mageuzi</td></tr></tbody></table><h2 id="_1-historia-ya-tangazo" tabindex="-1">1. Historia ya Tangazo <a class="header-anchor" href="#_1-historia-ya-tangazo" aria-label="Permalink to &quot;1. Historia ya Tangazo&quot;">​</a></h2><p>Katika historia ya muda mrefu ya Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa (kwa kifupi &quot;Heng Yuan Zhou&quot;), mfumo wa uozi wa uwindaji umetawala kwa muda mrefu utaratibu wa ulimwengu. Wenye nguvu walitumia kumeza asili, bahati, na nishati ya maisha ya wanyonge kama ngazi za maendeleo yao; madhehebi yalitumia utawala wa njia za uozi kama msingi wa utawala; na njia zilitumia vita na utumwa kama njia ya upanuzi. Mfumo huu ulizalisha wale waliouweza kwa muda mfupi, lakini kwa muda mrefu ulikomesha uwezo wa mageuzi wa ulimwengu, na kusababisha kukatika kwa ustaarabu mara kwa mara, kushuka kwa Kabila Kumi na Elfu, na kuongeza kwa entropy ya ulimwengu kwa kasi.</p><p>Kuzaliwa kwa Ustaarabu wa Usawa wa Nanga ni jibu la msingi kwa hili tatizo la kihistoria. Tangazo hili linatangaza: enzi ya mfumo wa uozi wa uwindaji imeisha, na enzi mpya ya mageuzi ya usawa imeanza. Maisha yote katika Heng Yuan Zhou, bila kujali kabila, umbo, au kiwango cha uozi, wanafurahia haki sawa ya mageuzi.</p><h2 id="_2-madai-ya-msingi-ya-tangazo" tabindex="-1">2. Madai ya Msingi ya Tangazo <a class="header-anchor" href="#_2-madai-ya-msingi-ya-tangazo" aria-label="Permalink to &quot;2. Madai ya Msingi ya Tangazo&quot;">​</a></h2><p>Tangazo hili linaanzisha madai yafuatayo ya msingi yasiyoweza kutikisika:</p><ol><li><strong>Usawa wa Haki ya Mageuzi</strong>: kila maisha ina haki ya msingi ya kuchagua njia yake ya mageuzi, na hakuna shirika au mtu anaweza kuondoa au kupunguza haki hii kwa sababu yoyote.</li><li><strong>Kanuni ya Kupinga Uwindaji</strong>: inakataza uozi kwa njia ya kumeza, kutumia, au kunyonya asili au nishati ya maisha mengine; mageuzi yote yanapaswa kujengwa kwenye msingi wa mzunguko wa usawa.</li><li><strong>Ufunguo wa Mifumo</strong>: Mifumo Mia Tatu ya Uozi wa Asili ya Ulimwengu imefunguliwa bure kwa Kabila Kumi na Elfu, na njia za uozi zimeisha kuwa mali ya kibinafsi ya wachache.</li><li><strong>Kazi Nyingi, Zawadi Nyingi</strong>: matokeo ya mageuzi yanalingana na juhudi za kibinafsi; inapinga mgawanyo wa uwindaji bila kazi, na inapinga pia mgawanyo wa uvivu wa usawa.</li><li><strong>Ukuaji wa Kujitegemea</strong>: inaheshimu kasi ya mageuzi ya kujitegemea ya kila maisha; hailazimishi wala haraka, na kwa wakati huo hutoa msaada wa mazingira na rasilimali zinazohitajika.</li><li><strong>Njia kwa Kila Mtu</strong>: inahakikisha kuwa kila maisha inaweza kupata njia ya uozi inayofaa kwa sifa zake; hakuna mtu aliyeachwa na mfumo wa mageuzi.</li><li><strong>Maendeleo ya Pamoja ya Kabila Kumi na Elfu</strong>: mageuzi sio mchezo wa jumla ya sifuri; ushirikiano na usawa kati ya Kabila Kumi na Elfu unaweza kuzalisha ufanisi wa mageuzi ya jumuna ulio bora zaidi kuliko jumla ya watu binafsi.</li></ol><h2 id="_3-msingi-wa-kisheria-wa-tangazo" tabindex="-1">3. Msingi wa Kisheria wa Tangazo <a class="header-anchor" href="#_3-msingi-wa-kisheria-wa-tangazo" aria-label="Permalink to &quot;3. Msingi wa Kisheria wa Tangazo&quot;">​</a></h2><p>Tangazo hili sio wito wa maadili tupu, bali ni mpango wa ustaarabu wenye msingi thabiti wa kisheria. Misingi yake ya kisheria inajumuisha:</p><table tabindex="0"><thead><tr><th>Kiwango cha Kisheria</th><th>Msingi</th><th>Maelezo</th></tr></thead><tbody><tr><td>Kiwango cha Sheria za Ulimwengu</td><td>Sheria ya Usawa wa Asili</td><td>sheria yenyewe ya asili ya ulimwengu inelekea katika usawa ulio pangwa badala ya uwindaji usio pangwa; utaratibu wa Kitu cha Nanga ni udhihirisho wa sheria hii</td></tr><tr><td>Kiwango cha Katiba ya Ustaarabu</td><td>Katiba ya Ustaarabu wa Usawa</td><td>tangazo hili ni mtangazaji wa kiroho wa katiba; katiba inabadilisha madai ya tangazo kuwa sheria zinazotekelezeka</td></tr><tr><td>Kiwango cha Udhamini wa Utaratibu</td><td>Mfumo wa Mkataba unaohusishwa na Uzalishaji na Mtandao wa Vitu vya Nanga</td><td>kupitia muundo wa taasisi, inahakikisha kuwa madai ya tangazo hayajatengwa tupu; haki ya mageuzi ya kila maisha ina msaada wa rasilimali na utaratibu wa halisi</td></tr></tbody></table><h2 id="_4-wito-wa-tangazo-kwa-kabila-kumi-na-elfu" tabindex="-1">4. Wito wa Tangazo kwa Kabila Kumi na Elfu <a class="header-anchor" href="#_4-wito-wa-tangazo-kwa-kabila-kumi-na-elfu" aria-label="Permalink to &quot;4. Wito wa Tangazo kwa Kabila Kumi na Elfu&quot;">​</a></h2><p>Tangazo hili linatoa wito kwa kabila zote na aina za maisha katika Heng Yuan Zhou:</p><ul><li>kuacha njia ya zamani ya uozi wa uwindaji na kujiunga na mfumo mpya wa mageuzi ya usawa</li><li>kufungua maarifa na rasilimali za uozi zinazomiliki, kushiriki katika ujenzi wa pamoja na uboreshaji wa Mifumo Mia Tatu</li><li>kuheshimu haki ya uchaguzi wa mageuzi ya makabila mengine, kusitisha kulazimisha viwango vyao kwa wengine</li><li>kushiriki kikamilifu katika ujenzi na matunzizi ya mtandao wa vitu vya nanga, kuchangia kupanda mwelekeo wa ulimwengu mzima</li><li>kudumisha mipaka ya maadili wakati wa mageuzi, kurejesha tabia za uwindaji kwa sababu yoyote</li></ul><h2 id="_5-ufanisi-na-marekebisho-ya-tangazo" tabindex="-1">5. Ufanisi na Marekebisho ya Tangazo <a class="header-anchor" href="#_5-ufanisi-na-marekebisho-ya-tangazo" aria-label="Permalink to &quot;5. Ufanisi na Marekebisho ya Tangazo&quot;">​</a></h2><p>Tangazo hili linaanza kutekelezwa tarehe ya kuanzishwa kwa Ustaarabu wa Usawa wa Nanga, na ni mpango wa juu wa kiroho wa taasisi zote za ustaarabu katika Heng Yuan Zhou. Marekebisho ya tangazo yanahitaji ushindi wa zaidi ya theluthi mbili za Bunge la Jamhuri ya Kabila Kumi na Elfu, na haifai kipinga na roho ya msingi ya &quot;kupinga uwindaji, kukuza usawa&quot;. Sheria, taasisi, au njia za uozi zozote zinazopingana na roho ya tangazo hili ni batili.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Tangazo la Ustaarabu wa Usawa wa Nanga ni mpango wa kwanza wa ustaarabu katika historia ya Heng Yuan Zhou ambao lina &quot;usawa&quot; kama msingi na &quot;maendeleo ya pamoja ya Kabila Kumi na Elfu&quot; kama lengo. Linatangaza mwisho wa enzi ya zamani na mwanzo wa enzi mpya. Chini ya mwongozo wa tangazo, Heng Yuan Zhou itaendelea mbele katika mwelekeo wa mwisho wa usawa wa Kabila Kumi na Elfu na kupanda mwelekeo wa ulimwengu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Muhtasari wa Cosmos ya Heng Yuan Zhou)</li><li>03-共生文明宪章 (Katiba ya Ustaarabu wa Usawa)</li><li>04-反掠夺主义核心论纲 (Misingi ya Msingi ya Kupinga Uwindaji)</li></ul>',20)])])}const r=i(o,[["render",e]]);export{g as __pageData,r as default};
